- name: Select the historical, v1, or qualified successor authoring seed
  id: seed-selection
  uses: actions/github-script@v7
  env:
    PSC0_SH1_FULL_QUALIFICATION: ${{ (github.event_name == 'workflow_dispatch' && inputs.full) || contains(github.event.head_commit.message, '[sh1-qualify]') }}
  with:
    script: |
      const { mkdir, writeFile } = await import('node:fs/promises');
      const path = await import('node:path');
      const root = process.env.GITHUB_WORKSPACE + '/psc0';
      const seeds = await import(root + '/scripts/sh1-successor-seed.mjs');
      const selected = await seeds.readSelectedAuthoringSeed();
      const legacy = selected.parent ?? (selected.mode === 'qualified' ? selected : null);
      let legacyManifestPath = '';
      if (legacy) {
        legacyManifestPath = path.join(root, 'dist/sh1-seed-selection/parent-v1.json');
        await mkdir(path.dirname(legacyManifestPath), { recursive: true });
        await writeFile(legacyManifestPath, JSON.stringify(legacy.manifest, null, 2) + '\n');
      }
      for (const [name, value] of Object.entries({
        mode: selected.mode,
        'full-qualification': process.env.PSC0_SH1_FULL_QUALIFICATION === 'true',
        'node-version': selected.nodeVersion,
        'source-ref': selected.sourceRef,
        'compiler-path': selected.compilerPath,
        'cache-key': selected.cacheKey,
        'cache-directory': selected.cacheDirectory,
        'artifact-run-id': selected.artifactRunId,
        'artifact-name': selected.artifactName,
        'recovery-typescript-version': selected.recoveryTypeScriptVersion,
        'has-parent': Boolean(selected.parent),
        'legacy-source-ref': legacy?.sourceRef ?? '',
        'legacy-compiler-path': legacy?.compilerPath ?? '',
        'legacy-cache-key': legacy?.cacheKey ?? '',
        'legacy-cache-directory': legacy?.cacheDirectory ?? '',
        'legacy-artifact-run-id': legacy?.artifactRunId ?? '',
        'legacy-artifact-name': legacy?.artifactName ?? '',
        'legacy-manifest-path': legacyManifestPath,
      })) core.setOutput(name, value);

replacements.newText:
- name: Authenticate the selected R seed and TS7-only recovery policy
  id: seed-selection
  uses: actions/github-script@v7
  env:
    PSC0_SH1_FULL_QUALIFICATION: ${{ (github.event_name == 'workflow_dispatch' && inputs.full) || contains(github.event.head_commit.message, '[sh1-qualify]') }}
  with:
    script: |
      const { mkdir, writeFile } = await import('node:fs/promises');
      const path = await import('node:path');
      const root = process.env.GITHUB_WORKSPACE + '/psc0';
      const recovery = await import(root + '/scripts/sh1-native-seed-recovery.mjs');
      const { selected, policySha256, recipeSha256 } = await recovery.readNativeSeedRecoveryPolicy({ root });
      const directory = path.join(root, 'dist/sh1-seed-selection');
      await mkdir(directory, { recursive: true });
      await writeFile(path.join(directory, 'selected-native-recovery.json'), JSON.stringify({
        sourceRef: selected.sourceRef, identitySha256: selected.identitySha256,
        policySha256, recipeSha256, recipe: recovery.nativeSeedRecoveryRecipe,
        parentMetadataRetained: Boolean(selected.parent),
        parentExecutionRequired: false, typescriptVersion: '7.0.2',
      }, null, 2) + '\n');
      for (const [name, value] of Object.entries({
        mode: selected.mode,
        'full-qualification': process.env.PSC0_SH1_FULL_QUALIFICATION === 'true',
        'node-version': selected.nodeVersion,
        'source-ref': selected.sourceRef,
        'compiler-path': selected.compilerPath,
        'cache-key': selected.cacheKey,
        'cache-directory': selected.cacheDirectory,
        'artifact-run-id': selected.artifactRunId,
        'artifact-name': selected.artifactName,
        'recovery-typescript-version': '7.0.2',
        'has-parent': Boolean(selected.parent),
      })) core.setOutput(name, value);

