- name: Restore the immutable v1 parent when a successor cache misses
  if: ${{ steps.seed-selection.outputs.full-qualification == 'true' && steps.seed-selection.outputs.has-parent == 'true' && steps.selected-cache-check.outputs.qualified-valid != 'true' }}
  id: parent-cache
  uses: actions/cache/restore@v4
  with:
    path: psc0/${{ steps.seed-selection.outputs.legacy-cache-directory }}
    key: ${{ steps.seed-selection.outputs.legacy-cache-key }}
- name: Route only the recovery edges whose exact cache is missing
  if: ${{ steps.seed-selection.outputs.full-qualification == 'true' }}
  id: seed-cache-check
  uses: actions/github-script@v7
  env:
    PSC0_SELECTED_SEED_VALID: ${{ steps.selected-cache-check.outputs.qualified-valid }}
  with:
    script: |
      const root = process.env.GITHUB_WORKSPACE + '/psc0';
      const seeds = await import(root + '/scripts/sh1-successor-seed.mjs');
      const selected = await seeds.readSelectedAuthoringSeed();
      const selectedValid = process.env.PSC0_SELECTED_SEED_VALID === 'true';
      const legacy = selected.parent ?? (selected.mode === 'qualified' ? selected : null);
      const legacyValid = legacy && await seeds.verifyAuthoringSeedCache(
        root + '/' + legacy.cacheDirectory, legacy.manifest);
      core.setOutput('qualified-valid', selectedValid);
      core.setOutput('needs-historical', !selectedValid && !legacyValid);
      core.setOutput('needs-qualified-recovery', !selectedValid && Boolean(legacy) && !legacyValid);
      core.setOutput('needs-successor-recovery', !selectedValid && Boolean(selected.parent));
- name: Preserve an immutable historical source checkout when recovery needs it
  if: ${{ steps.seed-cache-check.outputs.needs-historical == 'true' }}
  uses: actions/checkout@v4
  with:
    ref: 37f63c39d4a07189938046c64152bba25d789450
    path: historical-source
    sparse-checkout: psc0
- name: Restore historical native build
  if: ${{ steps.seed-cache-check.outputs.needs-historical == 'true' }}
  id: historical-lake
  uses: actions/cache/restore@v4
  with:
    path: historical-source/psc0/.lake/build
    key: psc0-sh1-historical-lake-v1-${{ runner.os }}-${{ runner.arch }}-37f63c39d4a07189938046c64152bba25d789450
- name: Identify the pinned recovery recipe and toolchain
  env:
    PSC0_TSC: ${{ steps.typescript.outputs.historical-cli }}
    PSC0_TYPESCRIPT_VERSION: '5.8.3'
    PATH: ${{ steps.typescript.outputs.historical-path }}
  if: ${{ steps.seed-cache-check.outputs.needs-historical == 'true' }}
  id: seed-identity
  run: node scripts/sh1-qualify.mjs seed-identity --source ../historical-source/psc0
- name: Restore exact historical seed
  if: ${{ steps.seed-cache-check.outputs.needs-historical == 'true' }}
  id: seed-cache
  uses: actions/cache/restore@v4
  with:
    path: psc0/.selfhost-seeds/37f63c39d4a07189938046c64152bba25d789450
    key: psc0-sh1-seed-v1-${{ steps.seed-identity.outputs.identity }}
- name: Verify seed digests or recover once from the preserved source
  env:
    PSC0_TSC: ${{ steps.typescript.outputs.historical-cli }}
    PSC0_TYPESCRIPT_VERSION: '5.8.3'
    PATH: ${{ steps.typescript.outputs.historical-path }}
  if: ${{ steps.seed-cache-check.outputs.needs-historical == 'true' }}
  run: node scripts/sh1-qualify.mjs recover-seed --source ../historical-source/psc0 --out .selfhost-seeds/37f63c39d4a07189938046c64152bba25d789450
- name: Retain historical native outputs before testing changed source
  if: ${{ steps.seed-cache-check.outputs.needs-historical == 'true' && steps.historical-lake.outputs.cache-hit != 'true' }}
  uses: actions/cache/save@v4
  with:
    path: historical-source/psc0/.lake/build
    key: ${{ steps.historical-lake.outputs.cache-primary-key }}
- name: Retain verified seed before testing changed source
  if: ${{ steps.seed-cache-check.outputs.needs-historical == 'true' && steps.seed-cache.outputs.cache-hit != 'true' }}
  uses: actions/cache/save@v4
  with:
    path: psc0/.selfhost-seeds/37f63c39d4a07189938046c64152bba25d789450
    key: ${{ steps.seed-cache.outputs.cache-primary-key }}
- name: Retrieve the immutable v1 parent artifact if it is still retained
  if: ${{ steps.seed-cache-check.outputs.needs-qualified-recovery == 'true' && steps.seed-selection.outputs.legacy-artifact-run-id != '' }}
  continue-on-error: true
  uses: actions/download-artifact@v4
  with:
    name: ${{ steps.seed-selection.outputs.legacy-artifact-name }}
    run-id: ${{ steps.seed-selection.outputs.legacy-artifact-run-id }}
    github-token: ${{ github.token }}
    path: qualified-artifact
- name: Read the immutable v1 source only when its bytes need recovery
  if: ${{ steps.seed-cache-check.outputs.needs-qualified-recovery == 'true' }}
  uses: actions/checkout@v4
  with:
    ref: ${{ steps.seed-selection.outputs.legacy-source-ref }}
    path: qualified-source
    sparse-checkout: psc0
- name: Verify or recover the v1 seed with its original TypeScript replay
  env:
    PSC0_TSC: ${{ steps.typescript.outputs.historical-cli }}
    PSC0_TYPESCRIPT_VERSION: '5.8.3'
    PATH: ${{ steps.typescript.outputs.historical-path }}
    PSC0_V1_MANIFEST: ${{ steps.seed-selection.outputs.legacy-manifest-path }}
  if: ${{ steps.seed-selection.outputs.full-qualification == 'true' && steps.seed-selection.outputs.mode == 'qualified' && (steps.seed-selection.outputs.recovery-typescript-version == '5.8.3' || steps.seed-cache-check.outputs.needs-successor-recovery == 'true') }}
  run: node scripts/sh1-qualify.mjs recover-qualified-seed --manifest "$PSC0_V1_MANIFEST" --source ../qualified-source/psc0 --artifact ../qualified-artifact/dist/sh1 --out dist/sh1-seed-recovery
- name: Retain recovered immutable parent bytes before successor recovery
  if: ${{ steps.seed-selection.outputs.has-parent == 'true' && steps.seed-cache-check.outputs.needs-qualified-recovery == 'true' && steps.parent-cache.outputs.cache-hit != 'true' }}
  uses: actions/cache/save@v4
  with:
    path: psc0/${{ steps.seed-selection.outputs.legacy-cache-directory }}
    key: ${{ steps.seed-selection.outputs.legacy-cache-key }}
- name: Read the selected successor's pinned recovery runner and source
  if: ${{ steps.seed-cache-check.outputs.needs-successor-recovery == 'true' }}
  uses: actions/checkout@v4
  with:
    ref: ${{ steps.seed-selection.outputs.source-ref }}
    path: successor-source
    sparse-checkout: psc0
- name: Retrieve the selected successor artifact when retained
  if: ${{ steps.seed-cache-check.outputs.needs-successor-recovery == 'true' && steps.seed-selection.outputs.artifact-run-id != '' }}
  continue-on-error: true
  uses: actions/download-artifact@v4
  with:
    name: ${{ steps.seed-selection.outputs.artifact-name }}
    run-id: ${{ steps.seed-selection.outputs.artifact-run-id }}
    github-token: ${{ github.token }}
    path: successor-artifact
- name: Recover a missing successor with its own pinned runner under TypeScript 7
  if: ${{ steps.seed-cache-check.outputs.needs-successor-recovery == 'true' }}
  working-directory: successor-source/psc0
  env:
    PSC0_TSC: ${{ steps.typescript.outputs.current-cli }}
    PSC0_TYPESCRIPT_VERSION: '7.0.2'
    PSC0_PARENT_COMPILER: ${{ github.workspace }}/psc0/${{ steps.seed-selection.outputs.legacy-compiler-path }}
    PSC0_SUCCESSOR_CACHE: ${{ github.workspace }}/psc0/${{ steps.seed-selection.outputs.cache-directory }}
  run: |
    node scripts/sh1-qualify.mjs recover-successor-seed \
      --manifest "$GITHUB_WORKSPACE/psc0/selfhost-seed.json" \
      --parent "$PSC0_PARENT_COMPILER" \
      --cache-directory "$PSC0_SUCCESSOR_CACHE" \
      --artifact "$GITHUB_WORKSPACE/successor-artifact/dist/sh1" \
      --out "$GITHUB_WORKSPACE/psc0/dist/sh1-successor-seed-recovery"

- name: Report retained seed IR type-argument findings
  if: ${{ steps.seed-selection.outputs.full-qualification == 'true' && steps.seed-selection.outputs.mode == 'qualified' }}
  run: |
    node --input-type=module <<'NODE'
    import { readFile } from 'node:fs/promises';
    const paths = [
      '../qualified-artifact/dist/sh1/C3/original-ir-inventory.json',
      'dist/sh1-seed-recovery/C2/original-ir-inventory.json',
    ];
    let reported = false;
    for (const path of paths) {
      let report;
      try { report = JSON.parse(await readFile(path, 'utf8')); }
      catch (error) {
        if (error.code !== 'ENOENT') console.log('PSC0_SH1_IR_DETAIL_UNAVAILABLE: ' + path + ': ' + error.message);
        continue;
      }
      if (report?.kind !== 'psc0-original-ir-inventory' || !Array.isArray(report.findings)) {
        console.log('PSC0_SH1_IR_DETAIL_UNAVAILABLE: ' + path + ': unexpected report shape');
        continue;
      }
      const findings = report.findings.filter(item => item?.code === 'call-type-arity');
      console.log('PSC0_SH1_IR_DETAIL_COUNTS: ' + JSON.stringify({
        path, traversalComplete: report.traversalComplete, findingCounts: report.findingCounts,
        printedTypeArityFindings: findings.length, omittedFindingDetails: report.omittedFindingDetails,
      }));
      for (const finding of findings) console.log('PSC0_SH1_IR_TYPE_ARITY: ' + JSON.stringify(finding));
      reported = true;
      break;
    }
    if (!reported) console.log('PSC0_SH1_IR_DETAIL_SKIP: no readable retained or recovery original-IR report');
    NODE

successor-recovery:
  needs: compiler
  if: ${{ needs.compiler.outputs.qualified == 'true' && needs.compiler.outputs.successor-candidate == 'true' }}
  runs-on: ubuntu-latest
  timeout-minutes: 90
  outputs:
    recovered: ${{ steps.recovery-receipt.outputs.recovered }}
    receipt-sha256: ${{ steps.recovery-receipt.outputs.receipt-sha256 }}
  defaults:
    run:
      working-directory: psc0
  steps:
    - name: Read the exact qualified successor revision and its recovery runner
      uses: actions/checkout@v4
      with:
        ref: ${{ github.sha }}
    - uses: actions/setup-node@v4
      with:
        node-version: ${{ needs.compiler.outputs.node-version }}
    - uses: leanprover/lean-action@v1
      with:
        lake-package-directory: psc0
        auto-config: false
        build: false
        test: false
        use-github-cache: false
        use-mathlib-cache: false
    - name: Install the pinned TypeScript 7 recovery compiler in isolation
      run: |
        npm install --prefix "$RUNNER_TEMP/psc0-typescript-7.0.2" --ignore-scripts --save-exact --no-audit --no-fund typescript@7.0.2
        node --input-type=module <<'NODE'
        import assert from 'node:assert/strict';
        import { appendFileSync, copyFileSync, mkdirSync, readFileSync, realpathSync } from 'node:fs';
        import path from 'node:path';
        import { createRequire } from 'node:module';
        import { spawnSync } from 'node:child_process';
        const require = createRequire(import.meta.url);
        const prefix = path.join(process.env.RUNNER_TEMP, 'psc0-typescript-7.0.2');
        const manifestPath = require.resolve('typescript/package.json', { paths: [prefix] });
        const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
        assert.equal(manifest.name, 'typescript');
        assert.equal(manifest.version, '7.0.2');
        const bin = typeof manifest.bin === 'string' ? manifest.bin : manifest.bin?.tsc;
        assert.equal(typeof bin, 'string', 'PSC0_TYPESCRIPT_BIN_METADATA');
        const launcher = realpathSync(path.resolve(path.dirname(manifestPath), bin));
        const result = spawnSync(process.execPath, [launcher, '--version'], { encoding: 'utf8' });
        assert.equal(result.status, 0, result.stderr);
        assert.equal(result.stdout.trim(), 'Version 7.0.2');
        appendFileSync(process.env.GITHUB_ENV, 'PSC0_TSC=' + launcher + '\nPSC0_TYPESCRIPT_VERSION=7.0.2\n');
        const directory = path.resolve('dist/typescript-profile/successor-cold');
        mkdirSync(directory, { recursive: true });
        copyFileSync(path.join(prefix, 'package-lock.json'), path.join(directory, 'package-lock.json'));
        copyFileSync(manifestPath, path.join(directory, 'package.json'));
        NODE
    - name: Read the candidate descriptor and its immutable parent bytes from this run
      uses: actions/download-artifact@v4
      with:
        name: psc0-sh1-ts7.0.2-${{ github.sha }}
        path: recovery-input
    - name: Select the provisional successor without activating it
      id: successor-selection
      uses: actions/github-script@v7
      with:
        script: |
          const assert = (await import('node:assert/strict')).default;
          const { readFile } = await import('node:fs/promises');
          const { existsSync } = await import('node:fs');
          const path = await import('node:path');
          const workspace = process.env.GITHUB_WORKSPACE;
          const { successorSeedSelection, verifyAuthoringSeedCache } = await import(
            workspace + '/psc0/scripts/sh1-successor-seed.mjs');
          const manifestPath = path.join(workspace, 'recovery-input/dist/sh1/seed-promotion.json');
          const manifest = JSON.parse(await readFile(manifestPath, 'utf8'));
          const selected = successorSeedSelection(manifest);
          assert.equal(selected.sourceRef, context.sha, 'PSC0_SH1_COLD_SOURCE_REF');
          assert.equal(String(manifest.qualification.runId), process.env.GITHUB_RUN_ID,
            'PSC0_SH1_COLD_QUALIFICATION_RUN');
          const parentPath = path.join(workspace, 'recovery-input', selected.parent.compilerPath);
          assert(await verifyAuthoringSeedCache(path.dirname(parentPath), selected.parent.manifest),
            'PSC0_SH1_COLD_PARENT_CACHE_REQUIRED');
          const cachePath = path.join(workspace, 'psc0', selected.cacheDirectory);
          const outputPath = path.join(workspace, 'psc0/dist/sh1-successor-cold');
          assert(!existsSync(cachePath), 'PSC0_SH1_COLD_CACHE_MUST_BE_ABSENT');
          assert(!existsSync(outputPath), 'PSC0_SH1_COLD_OUTPUT_MUST_BE_ABSENT');
          for (const [name, value] of Object.entries({
            'manifest-path': manifestPath, 'parent-compiler-path': parentPath,
            'cache-path': cachePath, 'cache-directory': selected.cacheDirectory,
            'cache-key': selected.cacheKey, 'output-path': outputPath,
          })) core.setOutput(name, value);
    - name: Rebuild the successor from its parent into fresh output and cache directories
      id: cold-recovery
      env:
        PSC0_SUCCESSOR_MANIFEST: ${{ steps.successor-selection.outputs.manifest-path }}
        PSC0_PARENT_COMPILER: ${{ steps.successor-selection.outputs.parent-compiler-path }}
        PSC0_SUCCESSOR_CACHE: ${{ steps.successor-selection.outputs.cache-path }}
        PSC0_RECOVERY_OUTPUT: ${{ steps.successor-selection.outputs.output-path }}
      run: |
        node scripts/sh1-qualify.mjs recover-successor-seed \
          --manifest "$PSC0_SUCCESSOR_MANIFEST" \
          --parent "$PSC0_PARENT_COMPILER" \
          --cache-directory "$PSC0_SUCCESSOR_CACHE" \
          --out "$PSC0_RECOVERY_OUTPUT" --cold
    - name: Authenticate the cold recovery receipt and the rebuilt successor bytes
      id: recovery-receipt
      uses: actions/github-script@v7
      env:
        PSC0_SUCCESSOR_MANIFEST: ${{ steps.successor-selection.outputs.manifest-path }}
        PSC0_SUCCESSOR_CACHE: ${{ steps.successor-selection.outputs.cache-path }}
        PSC0_RECOVERY_OUTPUT: ${{ steps.successor-selection.outputs.output-path }}
      with:
        script: |
          const assert = (await import('node:assert/strict')).default;
          const { readFile, copyFile } = await import('node:fs/promises');
          const { createHash } = await import('node:crypto');
          const path = await import('node:path');
          const { successorSeedSelection, verifyAuthoringSeedCache } = await import(
            process.env.GITHUB_WORKSPACE + '/psc0/scripts/sh1-successor-seed.mjs');
          const manifest = JSON.parse(await readFile(process.env.PSC0_SUCCESSOR_MANIFEST, 'utf8'));
          const selected = successorSeedSelection(manifest);
          const bytes = await readFile(path.join(process.env.PSC0_RECOVERY_OUTPUT, 'receipt.json'));
          const receipt = JSON.parse(bytes.toString('utf8'));
          assert.equal(receipt.evidence, 'qualified-successor-cold-recovery');
          assert.equal(receipt.passed, true);
          assert.equal(receipt.coldSuccessorRecovery, true);
          assert.equal(receipt.selectedSeedChanged, false);
          assert.equal(receipt.sourceRef, selected.sourceRef);
          assert.equal(receipt.successorIdentitySha256, selected.identitySha256);
          assert.deepEqual(receipt.actualFirstGenerationArtifacts, manifest.expectedFirstGenerationArtifacts);
          assert.deepEqual(receipt.actualArtifacts, manifest.expectedArtifacts);
          assert(await verifyAuthoringSeedCache(process.env.PSC0_SUCCESSOR_CACHE, manifest),
            'PSC0_SH1_COLD_RECOVERED_CACHE_REQUIRED');
          await copyFile(process.env.PSC0_SUCCESSOR_MANIFEST,
            path.join(process.env.PSC0_RECOVERY_OUTPUT, 'seed-promotion.json'));
          core.setOutput('receipt-sha256', createHash('sha256').update(bytes).digest('hex'));
          core.setOutput('recovered', true);
    - name: Retain the independent recovery receipt, exact products, and rebuilt cache
      if: always()
      uses: actions/upload-artifact@v4
      with:
        name: psc0-sh1-successor-recovery-ts7.0.2-${{ github.sha }}
        path: |
          psc0/dist/sh1-successor-cold
          psc0/.selfhost-seeds/successors
          psc0/dist/typescript-profile/successor-cold
        include-hidden-files: true
        if-no-files-found: ignore
        retention-days: 30
